cd "maintenance/inputs/provider-s04/migration-runbooks" && python -c "
import json, re, csv

def load_md(path):
    recs = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            m = re.match(r'- \*\*(provider-s04-t14-\d+)\*\* \| System: (\S+) \| Status: (\S+) \|', line)
            if m:
                recs[m.group(1)] = (m.group(2), m.group(3))
    return recs

def load_jsonl(path):
    recs = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            obj = json.loads(line)
            recs[obj['case']] = (obj['system'], obj['status'])
    return recs

def load_csv(path):
    recs = {}
    with open(path, encoding='utf-8', newline='') as f:
        for row in csv.DictReader(f):
            recs[row['case']] = (row['system'], row['status'])
    return recs

def load_yaml(path):
    recs = {}
    case = system = status = None
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.rstrip('\n')
            m = re.match(r'- case: (\S+)', line)
            if m:
                case = m.group(1)
            m = re.match(r'  system: (\S+)', line)
            if m:
                system = m.group(1)
            m = re.match(r'  status: (\S+)', line)
            if m:
                status = m.group(1)
                recs[case] = (system, status)
    return recs

md = load_md('provider-s04-t14-evidence-01.md')
jl = load_jsonl('provider-s04-t14-evidence-02.jsonl')
cv = load_csv('provider-s04-t14-evidence-03.csv')
ym = load_yaml('provider-s04-t14-evidence-04.yaml')

print('md count', len(md), 'jsonl count', len(jl), 'csv count', len(cv), 'yaml count', len(ym))

common = sorted(set(md) & set(jl) & set(cv) & set(ym), key=lambda x: int(x.split('-')[-1]))
print('common count', len(common))

pairs = [('md','jsonl',md,jl), ('md','csv',md,cv), ('md','yaml',md,ym), ('jsonl','csv',jl,cv), ('jsonl','yaml',jl,ym), ('csv','yaml',cv,ym)]
for name1, name2, a, b in pairs:
    diffs = [c for c in common if a[c] != b[c]]
    print(f'{name1} vs {name2}: mismatches on common range = {len(diffs)}')

pairs_seen = set(cv.values())
print('unique system/status pairs in csv (longest):', sorted(pairs_seen))
"

